package uk.ac.ravensbourne.casevault.security;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class SecurityConfigurationTest { @Autowired MockMvc mvc; @Test void tAuth008CsrfRequiredOnLogout(){try{mvc.perform(post("/logout")).andExpect(status().isForbidden());mvc.perform(post("/logout").with(csrf())).andExpect(status().is3xxRedirection());}catch(Exception e){throw new AssertionError(e);}} @Test void tAuth002And003GenericLoginFailure(){try{mvc.perform(post("/login").with(csrf()).param("username","unknown@example.test").param("password","bad-password")).andExpect(redirectedUrl("/login?error"));}catch(Exception e){throw new AssertionError(e);}} }
